// node js.mjs <engine-index.js> <op> <doc> <iters>
import { readFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'
const [eng, op, doc, itersS] = process.argv.slice(2)
const m = await import(pathToFileURL(eng).href)
const src = readFileSync(doc, 'utf8')
const fns = {
  render: () => m.carveToHtml(src),
  ast: () => m.parse(src),
  fmt: () => m.carveToCarve(src),
  lint: () => m.lintCarve(src, {}),
}
const f = fns[op]
const iters = Number(itersS)
for (let i = 0; i < Math.min(10, iters); i++) f()
const t = process.hrtime.bigint()
for (let i = 0; i < iters; i++) f()
console.log(JSON.stringify({ ms: Number(process.hrtime.bigint() - t) / 1e6 / iters }))

