use std::time::Instant;
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let (op, doc, iters) = (a[1].as_str(), &a[2], a[3].parse::<u32>().unwrap());
    let src = std::fs::read_to_string(doc).unwrap();
    let f = |s: &str| -> usize {
        match op {
            "render" => carve::to_html(s).len(),
            "ast" => { let d = carve::parse(s); std::hint::black_box(&d); 1 }
            "fmt" => carve::to_carve(s).len(),
            "lint" => carve::lint_carve(s).len(),
            _ => panic!("op"),
        }
    };
    for _ in 0..iters.min(10) { std::hint::black_box(f(&src)); }
    let t = Instant::now();
    for _ in 0..iters { std::hint::black_box(f(&src)); }
    println!("{{\"ms\":{}}}", t.elapsed().as_secs_f64() * 1000.0 / iters as f64);
}

