// node ab.mjs <engine> <op> <doc> <iters> <reps> [A=label:path] [B=label:path] >> out.jsonl
// Interleaves A/B (alternating which goes first) and prints JSON lines.
import { execFileSync } from 'node:child_process'
const W = 'WORKSPACE'
const PHPF = ['-n', '-d', 'extension=ctype', '-d', 'extension=mbstring', '-d', 'zend_extension=opcache', '-d', 'opcache.enable_cli=1', '-d', 'opcache.jit=tracing', '-d', 'opcache.jit_buffer_size=128M', '-d', 'memory_limit=4G']
const [engine, op, doc, iters, reps, a, b] = process.argv.slice(2)
const variants = [a ?? 'rel', b ?? 'main'].map((s) => {
  const [label, path] = s.split(':')
  return { label, path }
})
function cmd(v) {
  if (engine === 'js') return ['node', [`${W}/_ab/js.mjs`, v.path ?? `${W}/${v.label === 'rel' ? 'carve-js-rel' : 'carve-js'}/dist/index.js`, op, doc, iters]]
  if (engine === 'php') return ['php', [...PHPF, `${W}/_ab/php.php`, v.path ?? `${W}/${v.label === 'rel' ? 'carve-php-rel' : 'carve-php'}/src`, op, doc, iters]]
  return [v.path ?? `${W}/_ab/rs-${v.label}`, [op, doc, iters]]
}
for (let r = 0; r < Number(reps); r++) {
  const order = r % 2 ? [...variants].reverse() : variants
  for (const v of order) {
    const [c, args] = cmd(v)
    let ms = null
    try {
      const out = execFileSync(c, args, { encoding: 'utf8', maxBuffer: 1 << 26, timeout: 900000 })
      ms = JSON.parse(out.trim().split('\n').pop()).ms
    } catch (e) { ms = null }
    console.log(JSON.stringify({ engine, op, doc: doc.split('/').pop(), variant: v.label, rep: r, ms, load: Number(require_load()) }))
  }
}
function require_load() { return execFileSync('cat', ['/proc/loadavg'], { encoding: 'utf8' }).split(' ')[0] }

