// node multi.mjs <engine> <op> <doc> <iters> <reps> label:path ...  -> median per label
// engine rs: path = binary; js: path = dist/index.js; php: path = src dir
import { execFileSync } from 'node:child_process'
const W = 'WORKSPACE'
const PHPF = ['-n', '-d', 'extension=ctype', '-d', 'extension=mbstring', '-d', 'zend_extension=opcache', '-d', 'opcache.enable_cli=1', '-d', 'opcache.jit=tracing', '-d', 'opcache.jit_buffer_size=128M', '-d', 'memory_limit=4G']
const [engine, op, doc, iters, reps, ...vs] = process.argv.slice(2)
const variants = vs.map((s) => { const i = s.indexOf(':'); return { label: s.slice(0, i), path: s.slice(i + 1) } })
const res = Object.fromEntries(variants.map((v) => [v.label, []]))
for (let r = 0; r < Number(reps); r++) {
  const order = variants.map((_, i) => variants[(i + r) % variants.length])
  for (const v of order) {
    const [c, a] = engine === 'js' ? ['node', [`${W}/_ab/js.mjs`, v.path, op, doc, iters]]
      : engine === 'php' ? ['php', [...PHPF, `${W}/_ab/php.php`, v.path, op, doc, iters]]
      : [v.path, [op, doc, iters]]
    try { res[v.label].push(JSON.parse(execFileSync(c, a, { encoding: 'utf8', maxBuffer: 1 << 26 }).trim().split('\n').pop()).ms) } catch { res[v.label].push(null) }
  }
}
const med = (xs) => { const s = xs.filter((x) => x != null).sort((a, b) => a - b); return s.length ? s[Math.floor((s.length - 1) / 2)] : null }
for (const v of variants) {
  const xs = res[v.label].filter((x) => x != null)
  console.log(`${engine} ${op} ${doc.split('/').pop()} ${v.label}\tmed ${med(xs)?.toFixed(3)}\t[${Math.min(...xs).toFixed(3)}-${Math.max(...xs).toFixed(3)}]`)
}

