// node scale.mjs <engine> <variant> <reps> <ops,comma> <shapes,comma> >> scale-<engine>.jsonl
import { execFileSync } from 'node:child_process'
const W = 'WORKSPACE'
const PHPF = ['-n', '-d', 'extension=ctype', '-d', 'extension=mbstring', '-d', 'zend_extension=opcache', '-d', 'opcache.enable_cli=1', '-d', 'opcache.jit=tracing', '-d', 'opcache.jit_buffer_size=128M', '-d', 'memory_limit=4G']
const [engine, variant, reps, opsS, shapesS] = process.argv.slice(2)
const sizes = ['2k', '8k', '32k', '128k']
function run(op, doc, iters) {
  let c, a
  if (engine === 'js') { c = 'node'; a = [`${W}/_ab/js.mjs`, `${W}/${variant === 'rel' ? 'carve-js-rel' : 'carve-js'}/dist/index.js`, op, doc, String(iters)] }
  else if (engine === 'php') { c = 'php'; a = [...PHPF, `${W}/_ab/php.php`, `${W}/${variant === 'rel' ? 'carve-php-rel' : 'carve-php'}/src`, op, doc, String(iters)] }
  else { c = `${W}/_ab/rs-${variant}`; a = [op, doc, String(iters)] }
  try { return JSON.parse(execFileSync(c, a, { encoding: 'utf8', maxBuffer: 1 << 26, timeout: 600000 }).trim().split('\n').pop()).ms } catch { return null }
}
for (const shape of shapesS.split(',')) for (const op of opsS.split(',')) {
  let skip = false
  for (const size of sizes) {
    if (skip) { console.log(JSON.stringify({ engine, variant, shape, op, size, ms: null, skipped: true })); continue }
    const doc = `${W}/_ab/scale/${shape}-${size}.crv`
    const cal = run(op, doc, 1)
    if (cal === null) { console.log(JSON.stringify({ engine, variant, shape, op, size, ms: null })); continue }
    const iters = Math.max(1, Math.min(3000, Math.ceil(600 / Math.max(cal, 0.001))))
    const ms = []
    for (let r = 0; r < Number(reps); r++) ms.push(run(op, doc, iters))
    console.log(JSON.stringify({ engine, variant, shape, op, size, iters, ms }))
    if (cal > 60000) skip = true
  }
}

