// node bisect-rs.mjs <name> <loIdx good> <hiIdx bad> <op> <doc> <iters> <threshold ms>
// Indices are 1-based lines of rs-fp.txt (first-parent commits after the release tag).
import { execFileSync } from 'node:child_process'
import { readFileSync, appendFileSync } from 'node:fs'
const W = '_ab'
const [eng, name, loS, hiS, op, doc, iters, thrS] = process.argv.slice(2)
const fp = readFileSync(`${W}/${eng}-fp.txt`, 'utf8').trim().split('\n')
let lo = Number(loS), hi = Number(hiS)
const thr = Number(thrS)
const PHPF = ['-n', '-d', 'extension=ctype', '-d', 'extension=mbstring', '-d', 'zend_extension=opcache', '-d', 'opcache.enable_cli=1', '-d', 'opcache.jit=tracing', '-d', 'opcache.jit_buffer_size=128M', '-d', 'memory_limit=4G']
const log = (s) => { appendFileSync(`${W}/bisect-${eng}-${name}.log`, s + '\n'); console.log(s) }
function time(bin) {
  const xs = []
  for (let r = 0; r < 5; r++) {
    const out = eng === 'php' ? execFileSync('php', [...PHPF, `${W}/php.php`, bin, op, doc, iters], { encoding: 'utf8' })
      : eng === 'js' ? execFileSync('node', [`${W}/js.mjs`, bin, op, doc, iters], { encoding: 'utf8' })
      : execFileSync(bin, [op, doc, iters], { encoding: 'utf8' })
    xs.push(JSON.parse(out.trim().split('\n').pop()).ms)
  }
  xs.sort((a, b) => a - b)
  return xs[2]
}
log(`bisect ${name}: good ${fp[lo - 1]} bad ${fp[hi - 1]} thr ${thr}`)
while (hi - lo > 1) {
  const mid = Math.floor((lo + hi) / 2)
  const sha = fp[mid - 1].split(' ')[0]
  const bin = execFileSync(`${W}/${eng === 'rs' ? 'build-rs-at.sh' : eng + '-at.sh'}`, [sha], { encoding: 'utf8' }).trim().split('\n').pop()
  const ms = time(bin)
  const bad = ms > thr
  log(`  ${mid} ${fp[mid - 1]} -> ${ms.toFixed(3)} ${bad ? 'BAD' : 'good'}`)
  if (bad) hi = mid; else lo = mid
}
log(`RESULT ${name}: first bad ${fp[hi - 1]} (last good ${fp[lo - 1]})`)
